	private static string ResolveVoxelTopTexturePath(TerrainDef terrain)
	{
		var token = string.IsNullOrWhiteSpace(terrain.TopTile) ? terrain.StringId : terrain.TopTile;
		var fileName = ResolveVoxelFileName(token, isTop: true);
		return string.IsNullOrWhiteSpace(fileName) ? string.Empty : $"{VoxelTileRoot}/{fileName}";
	}

	private static string ResolveVoxelSideTexturePath(TerrainDef terrain)
	{
		var token = string.IsNullOrWhiteSpace(terrain.SideTile) ? terrain.StringId : terrain.SideTile;
		var fileName = ResolveVoxelFileName(token, isTop: false);
		return string.IsNullOrWhiteSpace(fileName) ? string.Empty : $"{VoxelTileRoot}/{fileName}";
	}

	private static string ResolveVoxelFileName(string token, bool isTop)
	{
		if (VoxelTileAliases.TryGetValue(token, out var alias))
			return alias;

		var inferred = token switch
		{
			"grass_block" => isTop ? "tile_grass_top.png" : "tile_grass_side.png",
			"grass" => isTop ? "tile_grass_top.png" : "tile_grass_side.png",
			"tree" => "tile_grass_side.png",
			"fungus" => "tile_grass_side.png",
			"dirt" => "tile_dirt.png",
			"swamp" => "tile_dirt.png",
			"marsh" => "tile_dirt.png",
			"sand" => "tile_dirt.png",
			"wall_soil" => "tile_dirt.png",
			"stone" => "tile_stone.png",
			"gravel" => "tile_stone.png",
			"mountain" => "tile_stone.png",
			"rubble" => "tile_stone.png",
			"floor" => "tile_stone.png",
			"wall_stone" => "tile_stone.png",
			"wall_granite" => "tile_stone.png",
			"wall_obsidian" => "tile_stone.png",
			"wall_iron" => "tile_stone.png",
			"crystal_vein" => "tile_stone.png",
			_ => string.Empty,
		};

		return inferred;
	}

	private static Image BuildTopDiamondFromTile(Image tileImage)
	{
		const int targetW = 128;
		const int targetH = 64;
		var result = Image.CreateEmpty(targetW, targetH, false, Image.Format.Rgba8);
		var srcW = tileImage.GetWidth();
		var srcH = tileImage.GetHeight();
		var halfW = targetW / 2f;
		var halfH = targetH / 2f;

		for (var y = 0; y < targetH; y++)
		{
			for (var x = 0; x < targetW; x++)
			{
				var nx = (x - halfW) / halfW;
				var ny = (y - halfH) / halfH;
				if (Math.Abs(nx) + Math.Abs(ny) > 1f)
				{
					result.SetPixel(x, y, Colors.Transparent);
					continue;
				}

				var u = (nx - ny + 1f) * 0.5f;
				var v = (nx + ny + 1f) * 0.5f;
				var sx = Math.Clamp((int)Math.Round(u * (srcW - 1)), 0, srcW - 1);
				var sy = Math.Clamp((int)Math.Round(v * (srcH - 1)), 0, srcH - 1);
				result.SetPixel(x, y, tileImage.GetPixel(sx, sy));
			}
		}

		return result;
	}

	private static Image EnhanceTopFaceEdges(Image diamond, float outlineStrength)
	{
		var width = diamond.GetWidth();
		var height = diamond.GetHeight();
		var outlined = (Image)diamond.Duplicate();
		outlineStrength = Math.Clamp(outlineStrength, 0f, 0.75f);

		for (var y = 1; y < height - 1; y++)
		for (var x = 1; x < width - 1; x++)
		{
			var c = diamond.GetPixel(x, y);
			if (c.A <= 0.01f)
				continue;

			var isEdge = diamond.GetPixel(x - 1, y).A <= 0.01f
				|| diamond.GetPixel(x + 1, y).A <= 0.01f
				|| diamond.GetPixel(x, y - 1).A <= 0.01f
				|| diamond.GetPixel(x, y + 1).A <= 0.01f;
			if (!isEdge)
				continue;

			var factor = 1f - outlineStrength;
			outlined.SetPixel(x, y, new Color(c.R * factor, c.G * factor, c.B * factor, c.A));
		}

		return outlined;
	}

	private static Image GenerateSideFaceFromTile(Image tileImage, bool isRight, float darken, int faceHeight)
	{
		var iw = SideTextureWidth;
		var ih = SideTextureHeight;
		var faceH = Math.Clamp(faceHeight, 24, ih - 8);
		var img = Image.CreateEmpty(iw, ih, false, Image.Format.Rgba8);
		var tw = tileImage.GetWidth();
		var th = tileImage.GetHeight();
		var gradientDepth = IsWallFaceHeight(faceH) ? 0.22f : 0.17f;

		for (var px = 0; px < iw; px++)
		{
			var t = px / (float)(iw - 1);
			var sampleX = isRight
				? (tw - 1) - (int)Math.Round(t * (tw - 1))
				: (int)Math.Round(t * (tw - 1));
			var pyStart = isRight
				? (int)((iw - 1 - px) * 0.5f)
				: (int)(px * 0.5f);

			for (var dy = 0; dy < faceH; dy++)
			{
				var py = pyStart + dy;
				if (py >= ih) break;

				var sampleY = Math.Clamp((int)Math.Round(((dy + (th - faceH)) / (float)(th - 1)) * (th - 1)), 0, th - 1);
				var color = SampleArea(tileImage, sampleX, sampleY, tw, th);
				var gradient = 1.0f - (dy / (float)faceH) * gradientDepth;
				var c = color * new Color(darken * gradient, darken * gradient, darken * gradient, 1f);
				c.A = color.A;
				img.SetPixel(px, py, c);
			}
		}

		return img;
	}

	private static float GetTopEdgeStrength(TerrainDef terrain)
	{
		if (IsWallTerrain(terrain))
			return WallTopEdgeStrength;
		return terrain.Solid ? SolidTopEdgeStrength : NonSolidTopEdgeStrength;
	}

	private static bool IsWallFaceHeight(int faceHeight) => faceHeight >= WallSideFaceHeight - 6;

	private static float GetSideEdgeStrength(TerrainDef terrain)
	{
		if (IsWallTerrain(terrain))
			return WallSideEdgeStrength;
		return terrain.Solid ? SolidSideEdgeStrength : NonSolidSideEdgeStrength;
	}

	private static bool IsWallTerrain(TerrainDef terrain)
	{
		return terrain.StringId.StartsWith("wall_", StringComparison.OrdinalIgnoreCase)
			|| terrain.StringId.Equals(Terrains.Stone, StringComparison.OrdinalIgnoreCase)
			|| terrain.StringId.Equals(Terrains.Dirt, StringComparison.OrdinalIgnoreCase)
			|| terrain.StringId.Equals(Terrains.Mountain, StringComparison.OrdinalIgnoreCase);
	}

	private static void EnhanceSideFaceEdge(Image sideFace, bool isRight, float edgeStrength)
	{
		edgeStrength = Math.Clamp(edgeStrength, 0f, 0.75f);
		if (edgeStrength <= 0f)
			return;

		var width = sideFace.GetWidth();
		var height = sideFace.GetHeight();
		for (var y = 0; y < height; y++)
		{
			var x = isRight ? width - 1 : 0;
			while (x >= 0 && x < width)
			{
				var c = sideFace.GetPixel(x, y);
				if (c.A > 0.01f)
				{
					var factor = 1f - edgeStrength;
					sideFace.SetPixel(x, y, new Color(c.R * factor, c.G * factor, c.B * factor, c.A));
					var nextX = isRight ? x - 1 : x + 1;
					if (nextX >= 0 && nextX < width)
					{
						var c2 = sideFace.GetPixel(nextX, y);
						if (c2.A > 0.01f)
						{
							var factor2 = 1f - edgeStrength * 0.5f;
							sideFace.SetPixel(nextX, y, new Color(c2.R * factor2, c2.G * factor2, c2.B * factor2, c2.A));
						}
					}
					break;
				}
				x += isRight ? -1 : 1;
			}
		}
	}

	/// <summary>
	/// Extract the top tile as an Image from an AtlasTexture or regular Texture2D.
	/// </summary>
	private static Image? ExtractImage(Texture2D texture)
	{
		if (texture is AtlasTexture atlas)
		{
			var fullImage = atlas.Atlas?.GetImage();
			if (fullImage == null) return null;
			var region = atlas.Region;
			return fullImage.GetRegion(new Rect2I(
				(int)region.Position.X, (int)region.Position.Y,
				(int)region.Size.X, (int)region.Size.Y));
		}
		return texture.GetImage();
	}

	/// <summary>
	/// Terrain atlas entries are packed isometric blocks, not pure top-face diamonds.
	/// Extract the visible top cap and mirror it into a standalone 128x64 diamond so
	/// procedural side generation does not sample the baked wall pixels.
	/// </summary>
	private static Image NormalizeTopImage(Image sourceImage)
	{
		if (!TryExtractTopDiamondFromPackedTile(sourceImage, out var normalized) || normalized == null)
			return sourceImage;
		return normalized;
	}

	private static bool TryExtractTopDiamondFromPackedTile(Image sourceImage, out Image? normalized)
	{
		normalized = null;
		var width = sourceImage.GetWidth();
		var height = sourceImage.GetHeight();
		var minX = width;
		var minY = height;
		var maxX = -1;
		var maxY = -1;
		var rowWidths = new int[height];

		for (var y = 0; y < height; y++)
		{
			var rowMinX = width;
			var rowMaxX = -1;
			for (var x = 0; x < width; x++)
			{
				if (sourceImage.GetPixel(x, y).A <= 0.01f)
					continue;

				rowMinX = Math.Min(rowMinX, x);
				rowMaxX = Math.Max(rowMaxX, x);
			}

			if (rowMaxX < 0)
				continue;

			rowWidths[y] = rowMaxX - rowMinX + 1;
			minX = Math.Min(minX, rowMinX);
			minY = Math.Min(minY, y);
			maxX = Math.Max(maxX, rowMaxX);
			maxY = Math.Max(maxY, y);
		}

		if (maxX < minX || maxY < minY)
			return false;

		if (!TryResolvePackedTileTopCap(rowWidths, minY, maxY, out var maxRowWidth, out var seamY, out _))
			return false;

		var targetWidth = (int)(IsoCoordUtil.TileHalfW * 2f);
		var targetHalfHeight = (int)IsoCoordUtil.TileHalfH;
		if (targetWidth <= 0 || targetHalfHeight <= 0)
			return false;

		var capHeight = seamY - minY + 1;
		var cap = sourceImage.GetRegion(new Rect2I(minX, minY, maxRowWidth, capHeight));
		cap.Resize(targetWidth, targetHalfHeight);

		var diamond = Image.CreateEmpty(targetWidth, targetHalfHeight * 2, false, Image.Format.Rgba8);
		for (var y = 0; y < targetHalfHeight; y++)
		{
			for (var x = 0; x < targetWidth; x++)
			{
				var pixel = cap.GetPixel(x, y);
				diamond.SetPixel(x, y, pixel);
				diamond.SetPixel(x, (targetHalfHeight * 2) - 1 - y, pixel);
			}
		}

		normalized = diamond;
		return true;
	}

	private static bool TryResolvePackedTileTopCap(int[] rowWidths, int minY, int maxY, out int maxRowWidth, out int seamY, out int plateauRows)
	{
		maxRowWidth = 0;
		seamY = -1;
		plateauRows = 0;
		if (rowWidths.Length == 0 || minY < 0 || maxY >= rowWidths.Length || minY >= maxY)
			return false;

		for (var y = minY; y <= maxY; y++)
			maxRowWidth = Math.Max(maxRowWidth, rowWidths[y]);

		if (maxRowWidth < 16)
			return false;

		for (var y = minY; y <= maxY; y++)
		{
			if (rowWidths[y] < maxRowWidth - 1)
			{
				if (seamY >= 0)
					break;
				continue;
			}

			if (seamY < 0)
				seamY = y;
			plateauRows++;
		}

		var capHeight = seamY - minY + 1;
		return seamY > minY && plateauRows >= 4 && capHeight >= 8;
	}

	/// <summary>
	/// Generate left side face as a 64x64 parallelogram image.
	/// The parallelogram covers the area below the diamond's bottom-left edge:
	///   TL=(0,0) TR=(63,31) BR=(63,63) BL=(0,32)  (in image coords)
	/// Colors are sampled from the left-bottom edge of the top diamond, darkened by LeftDarken.
	/// </summary>
	private static Image GenerateLeftSideImage(Image topImage)
	{
		const int iw = 64;
		const int ih = 64;
		const int faceH = 32;
		var img = Image.CreateEmpty(iw, ih, false, Image.Format.Rgba8);
		var tw = topImage.GetWidth();
		var th = topImage.GetHeight();
		var halfW = tw / 2;
		var halfH = th / 2;

		for (var px = 0; px < iw; px++)
		{
			var t = px / (float)(iw - 1);
			var sampleX = (int)(t * halfW);
			var sampleY = halfH + (int)(t * (halfH - 1));
			sampleX = Math.Clamp(sampleX, 0, tw - 1);
			sampleY = Math.Clamp(sampleY, 0, th - 1);
			var color = SampleArea(topImage, sampleX, sampleY, tw, th);

			var pyStart = (int)(px * 0.5f);
			for (var dy = 0; dy < faceH; dy++)
			{
				var py = pyStart + dy;
				if (py >= ih) break;
				var gradientFactor = 1.0f - (dy / (float)faceH) * 0.2f;
				var c = color * new Color(LeftDarken * gradientFactor, LeftDarken * gradientFactor, LeftDarken * gradientFactor, 1f);
				c.A = color.A;
				img.SetPixel(px, py, c);
			}
		}
		return img;
	}

	/// <summary>
	/// Generate right side face as a 64x64 parallelogram image.
	/// The parallelogram covers the area below the diamond's bottom-right edge:
	///   TL=(0,32) TR=(63,0) BR=(63,32) BL=(0,64)  (in image coords)
	/// Colors are sampled from the right-bottom edge of the top diamond, darkened by RightDarken.
	/// </summary>
	private static Image GenerateRightSideImage(Image topImage)
	{
		const int iw = 64;
		const int ih = 64;
		const int faceH = 32;
		var img = Image.CreateEmpty(iw, ih, false, Image.Format.Rgba8);
		var tw = topImage.GetWidth();
		var th = topImage.GetHeight();
		var halfW = tw / 2;
		var halfH = th / 2;

		for (var px = 0; px < iw; px++)
		{
			var t = px / (float)(iw - 1);
			var sampleX = halfW + (int)(t * (halfW - 1));
			var sampleY = (th - 1) - (int)(t * (halfH - 1));
			sampleX = Math.Clamp(sampleX, 0, tw - 1);
			sampleY = Math.Clamp(sampleY, 0, th - 1);
			var color = SampleArea(topImage, sampleX, sampleY, tw, th);

			var pyStart = (int)((iw - 1 - px) * 0.5f);
			for (var dy = 0; dy < faceH; dy++)
			{
				var py = pyStart + dy;
				if (py >= ih) break;
				var gradientFactor = 1.0f - (dy / (float)faceH) * 0.2f;
				var c = color * new Color(RightDarken * gradientFactor, RightDarken * gradientFactor, RightDarken * gradientFactor, 1f);
				c.A = color.A;
				img.SetPixel(px, py, c);
			}
		}
		return img;
	}

	/// <summary>Sample a 3x3 area around (cx,cy) and return the average color.</summary>
	private static Color SampleArea(Image img, int cx, int cy, int w, int h)
	{
		float r = 0, g = 0, b = 0, a = 0;
		var count = 0;
		for (var dy = -1; dy <= 1; dy++)
		for (var dx = -1; dx <= 1; dx++)
		{
			var sx = Math.Clamp(cx + dx, 0, w - 1);
			var sy = Math.Clamp(cy + dy, 0, h - 1);
			var c = img.GetPixel(sx, sy);
			if (c.A < 0.01f) continue; // skip transparent pixels
			r += c.R; g += c.G; b += c.B; a += c.A;
			count++;
		}
		if (count == 0) return new Color(0.5f, 0.5f, 0.5f);
		return new Color(r / count, g / count, b / count, a / count);
	}

	/// <summary>Create a solid-color diamond image (fallback when no atlas tile available).</summary>
	private static Image CreateDiamondImage(int w, int h, Color color)
	{
		var image = Image.CreateEmpty(w, h, false, Image.Format.Rgba8);
		var halfW = w / 2;
		var halfH = h / 2;
		for (var py = 0; py < h; py++)
		for (var px = 0; px < w; px++)
		{
			var dx = Math.Abs(px - halfW) / (float)halfW;
			var dy = Math.Abs(py - halfH) / (float)halfH;
			image.SetPixel(px, py, dx + dy <= 1.0f ? color : Colors.Transparent);
		}
		return image;
	}

	// ── Entity Rendering ──

	private static readonly Vector2 DefaultEntitySpriteScale = new(0.25f, 0.25f);
	private static readonly Vector2 EntitySpriteBaseOffset = new(0f, -8f);
	private readonly Dictionary<string, ImageTexture> _entityMarkerCache = new();

	private void CollectEntityCommands(int cx, int cy, int cz, int halfW, int halfH, int zMin, int zMax)
	{
		_entityCommands.Clear();

		foreach (var actor in _state.Actors.Values)
		{
			if (actor.Z < zMin || actor.Z > zMax) continue;
			if (Math.Abs(actor.X - cx) > halfW || Math.Abs(actor.Y - cy) > halfH) continue;
			var tint = GetVisionTint(actor.X, actor.Y, actor.Z);
			if (tint.A <= 0f) continue;
			var label = actor.Id == _state.PlayerId ? "P" : (actor.Faction == Factions.Hostile ? "!" : "?");
			_entityCommands.Add(new EntityDrawCommand(
				IsoCoordUtil.SortKey(actor.X, actor.Y, actor.Z),
				IsoCoordUtil.WorldToScreen(actor.X, actor.Y, actor.Z),
				actor,
				label,
				tint));
		}

		for (var wy = cy - halfH; wy <= cy + halfH; wy++)
		for (var wx = cx - halfW; wx <= cx + halfW; wx++)
		for (var wz = zMax; wz >= zMin; wz--)
		{
			var entities = _state.World!.GetEntities(wx, wy, wz);
			if (entities.Count == 0) continue;
			var tint = GetVisionTint(wx, wy, wz);
			if (tint.A <= 0f) continue;
			var pos = IsoCoordUtil.WorldToScreen(wx, wy, wz);
			var key = IsoCoordUtil.SortKey(wx, wy, wz);
			foreach (var e in entities)
				_entityCommands.Add(new EntityDrawCommand(key, pos, null, e.Glyph, tint));
		}

		_entityCommands.Sort(static (a, b) => a.SortKey.CompareTo(b.SortKey));
	}

	private void RenderScene()
	{
		_faceCommands.Clear();

		for (var i = 0; i < _drawCommands.Count; i++)
		{
			var terrain = _drawCommands[i];
			if (terrain.DrawTop) DrawBlockTop(terrain);
			if (terrain.DrawLeftSide) DrawLeftSide(terrain);
			if (terrain.DrawRightSide) DrawRightSide(terrain);
		}

		_faceCommands.Sort(static (a, b) => a.SortKey.CompareTo(b.SortKey));
		_faceBatchCanvas?.SetCommands(_faceCommands);

		for (var i = 0; i < _entityCommands.Count; i++)
		{
			var entity = _entityCommands[i];
			if (entity.Actor != null && TryDrawActorSprite(entity.ScreenPos, entity.Actor, entity.Tint))
				continue;
			DrawEntityMarker(entity.ScreenPos, entity.Label, entity.Tint);
		}

		RenderHoverHighlights();
	}

	private void CollectHoverHighlights(int cx, int cy, int cz, int halfW, int halfH, int zMin, int zMax)
	{
		_highlightCommands.Clear();
		_highlightCommandCount = 0;
		if (_parentModule?.HoverWorldCell is not { } hover)
			return;
		if (Math.Abs(hover.X - cx) > halfW || Math.Abs(hover.Y - cy) > halfH)
			return;
		if (hover.Z < zMin || hover.Z > zMax)
			return;
		if (_fogTracker.GetVisionBand(hover.X, hover.Y, hover.Z) == PlayerVisionBand.Unknown)
			return;

		var basePos = IsoCoordUtil.WorldToScreen(hover.X, hover.Y, hover.Z);
		_highlightCommands.Add(new HoverHighlightCommand(basePos, HoverCellTint, IsoCoordUtil.SortKey(hover.X, hover.Y, hover.Z) + 9000));

		var airPos = IsoCoordUtil.WorldToScreen(hover.X, hover.Y, hover.Z - 1);
		_highlightCommands.Add(new HoverHighlightCommand(airPos, HoverAirTint, IsoCoordUtil.SortKey(hover.X, hover.Y, hover.Z - 1) + 9001));
		_highlightCommands.Sort(static (a, b) => a.SortKey.CompareTo(b.SortKey));
		_highlightCommandCount = _highlightCommands.Count;
	}

	private void RenderHoverHighlights()
	{
		var pulse = 0.84f + 0.16f * (0.5f + 0.5f * Mathf.Sin(Time.GetTicksMsec() / 120.0f));
		for (var i = 0; i < _highlightCommands.Count; i++)
		{
			var command = _highlightCommands[i];
			var isAir = i > 0;
			var fillTint = command.Tint * new Color(1f, 1f, 1f, pulse);
			var outlineTint = isAir ? HoverAirOutlineTint : HoverCellOutlineTint;
			var outlineScale = isAir ? HoverAirOutlineScale : HoverCellOutlineScale;
			var fillScale = isAir ? HoverAirFillScale : HoverCellFillScale;
			DrawHoverDiamond(command.ScreenPos, outlineTint, outlineScale, zIndex: 2, textureKey: "hover_diamond_outline");
			DrawHoverDiamond(command.ScreenPos, fillTint, fillScale, zIndex: 3, textureKey: "hover_diamond_fill");
		}
	}

	private void DrawHoverDiamond(Vector2 pos, Color tint, Vector2 scale, int zIndex, string textureKey)
	{
		var sprite = AcquireSprite();
		sprite.Centered = true;
		sprite.Texture = GetEntityMarkerTexture(textureKey);
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Linear;
		sprite.RegionEnabled = false;
		sprite.Scale = scale;
		sprite.Position = pos;
		sprite.Skew = 0f;
		sprite.ZIndex = zIndex;
		sprite.Modulate = tint;
		sprite.Visible = true;
	}

	private bool TryDrawActorSprite(Vector2 pos, Actor actor, Color tint)
	{
		if (!TryResolveActorSpriteVisual(actor, out var visual))
			return false;

		var size = visual.Region?.Size ?? visual.Texture.GetSize();
		var sprite = AcquireSprite();
		sprite.Centered = false;
		sprite.Texture = visual.Texture;
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Nearest;
		sprite.RegionEnabled = visual.Region != null;
		if (visual.Region is { } region)
			sprite.RegionRect = region;
		sprite.Scale = visual.Scale;
		sprite.Skew = 0f;
		sprite.ZIndex = 1;
		sprite.Modulate = tint;
		sprite.Position = pos + EntitySpriteBaseOffset + visual.Offset + new Vector2(
			-(size.X * visual.Scale.X) / 2f,
			-(size.Y * visual.Scale.Y));
		sprite.Visible = true;
		return true;
	}

	private bool TryResolveActorSpriteVisual(Actor actor, out ActorSpriteVisual visual)
	{
		visual = default;
		var entry = ResolveActorRenderEntry(actor);
		if (entry == null)
			return false;

		Texture2D? texture = null;
		Rect2? region = null;
		if (IsTextureEntry(entry) && entry.TexturePath is { Length: > 0 } texturePath)
		{
			texture = ResAccess.Get<Texture2D>(texturePath);
			if (texture != null)
				region = ResolveEntitySpriteRegion(entry, actor, texture);
		}
		else if (IsSpriteSheetEntry(entry))
		{
			var sheetPath = ResolveCharacterSheetPath(entry);
			if (sheetPath.Length > 0)
			{
				texture = ResAccess.Get<Texture2D>(sheetPath);
				if (texture != null)
					region = ResolveCharacterSheetRegion(entry, actor, texture);
			}
		}

		if (texture == null)
			return false;

		visual = new ActorSpriteVisual(
			texture,
			region,
			ResolveEntitySpriteScale(entry.Scale),
			ResolveEntitySpriteOffset(entry.Offset));
		return true;
	}

	private static Vector2 ResolveEntitySpriteScale(float[]? scale)
	{
		if (scale is [var x, var y] && x > 0f && y > 0f)
			return new Vector2(x, y);
		return DefaultEntitySpriteScale;
	}

	private static Vector2 ResolveEntitySpriteOffset(float[]? offset)
	{
		if (offset is [var x, var y])
			return new Vector2(x, y);
		return Vector2.Zero;
	}

	private static Rect2? ResolveEntitySpriteRegion(ResAccess.RenderEntry entry, Actor actor, Texture2D texture)
	{
		if (!entry.UseFacing)
			return null;

		var textureWidth = (int)texture.GetWidth();
		var textureHeight = (int)texture.GetHeight();
		if (textureWidth <= 0 || textureHeight <= 0)
			return null;

		var frameWidth = entry.FrameWidth > 0 ? Math.Min(entry.FrameWidth, textureWidth) : textureWidth;
		var inferredFrameHeight = textureHeight % 8 == 0 ? textureHeight / 8 : textureHeight;
		var frameHeight = entry.FrameHeight > 0 ? Math.Min(entry.FrameHeight, textureHeight) : inferredFrameHeight;
		if (frameWidth <= 0 || frameHeight <= 0)
			return null;

		var rowCount = Math.Max(1, textureHeight / frameHeight);
		var row = Math.Clamp(
			DirectionalSpriteHelper.ResolveDirectionRow(actor.FacingX, actor.FacingY),
			0,
			rowCount - 1);
		return new Rect2(0, row * frameHeight, frameWidth, frameHeight);
	}

	private ResAccess.RenderEntry? ResolveActorRenderEntry(Actor actor)
	{
		if (actor.Id == _state.PlayerId)
		{
			var appearance = PlayerAppearanceCatalog.GetOrDefault(_state.PlayerAppearanceId);
			var tuning = ResAccess.GetEntry("player");
			return new ResAccess.RenderEntry
			{
				Type = "sprite_sheet",
				SheetDir = appearance.SheetDir,
				DefaultAnim = appearance.DefaultAnim,
				Scale = tuning?.Scale,
				Offset = tuning?.Offset,
				FrameWidth = tuning?.FrameWidth ?? 0,
				FrameHeight = tuning?.FrameHeight ?? 0,
				UseFacing = true,
			};
		}

		if (TryGetSupportedActorEntry(actor.Id, out var direct))
			return direct;
		if (!string.IsNullOrWhiteSpace(actor.TemplateId) && TryGetSupportedActorEntry(actor.TemplateId, out var template))
			return template;
		if (actor.Race?.Id is { Length: > 0 } raceId && TryGetSupportedActorEntry(raceId, out var race))
			return race;

		return null;
	}

	private static bool TryGetSupportedActorEntry(string key, out ResAccess.RenderEntry? entry)
	{
		entry = ResAccess.GetEntry(key);
		return IsTextureEntry(entry) || IsSpriteSheetEntry(entry);
	}

	private static bool IsSpriteSheetEntry(ResAccess.RenderEntry? entry) =>
		entry != null
		&& string.Equals(entry.Type, "sprite_sheet", StringComparison.OrdinalIgnoreCase)
		&& !string.IsNullOrWhiteSpace(entry.SheetDir);

	private static string ResolveCharacterSheetPath(ResAccess.RenderEntry entry)
	{
		if (string.IsNullOrWhiteSpace(entry.SheetDir))
			return string.Empty;
		var animationKey = string.IsNullOrWhiteSpace(entry.DefaultAnim) ? "Idle" : entry.DefaultAnim!;
		var sheetKey = CharacterSheetMap.TryGetValue(animationKey, out var resolved) ? resolved : "Idle";
		return $"{entry.SheetDir!.TrimEnd('/')}/{sheetKey}.png";
	}

	private static Rect2? ResolveCharacterSheetRegion(ResAccess.RenderEntry entry, Actor actor, Texture2D texture)
	{
		var textureWidth = (int)texture.GetWidth();
		var textureHeight = (int)texture.GetHeight();
		if (textureWidth <= 0 || textureHeight <= 0)
			return null;

		var frameWidth = entry.FrameWidth > 0
			? Math.Min(entry.FrameWidth, textureWidth)
			: Math.Min(DefaultCharacterSheetFrameWidth, textureWidth);
		var frameHeight = entry.FrameHeight > 0
			? Math.Min(entry.FrameHeight, textureHeight)
			: Math.Min(DefaultCharacterSheetFrameHeight, textureHeight);
		if (frameWidth <= 0 || frameHeight <= 0)
			return null;

		var rowCount = Math.Max(1, textureHeight / frameHeight);
		var row = Math.Clamp(
			DirectionalSpriteHelper.ResolveDirectionRow(actor.FacingX, actor.FacingY),
			0,
			rowCount - 1);
		return new Rect2(0, row * frameHeight, frameWidth, frameHeight);
	}

	private static bool IsTextureEntry(ResAccess.RenderEntry? entry) =>
		entry != null
		&& string.Equals(entry.Type, "texture", StringComparison.OrdinalIgnoreCase)
		&& !string.IsNullOrWhiteSpace(entry.TexturePath);

	private void DrawEntityMarker(Vector2 pos, string label, Color tint)
	{
		var s = AcquireSprite();
		s.Centered = true;
		s.RegionEnabled = false;
		s.Scale = Vector2.One;
		s.Texture = GetEntityMarkerTexture(label);
		s.Position = pos - new Vector2(0, IsoCoordUtil.TileHalfH * 0.5f);
		s.Skew = 0f;
		s.ZIndex = 1;
		s.Modulate = tint;
		s.Visible = true;
	}

	private ImageTexture GetEntityMarkerTexture(string label)
	{
		if (_entityMarkerCache.TryGetValue(label, out var cached)) return cached;
		const int size = 64;
		var image = Image.CreateEmpty(size, size, false, Image.Format.Rgba8);
		var center = (size - 1) * 0.5f;
		var radius = size * 0.5f - 4f;
		var color = label switch
		{
			"P" => new Color(0.2f, 0.6f, 1.0f),
			"!" => new Color(1.0f, 0.2f, 0.2f),
			"?" => new Color(0.2f, 0.8f, 0.2f),
			_ => Colors.White,
		};
		for (var py = 0; py < size; py++)
		for (var px = 0; px < size; px++)
		{
			if (label is "hover_diamond_fill" or "hover_diamond_outline")
			{
				var nx = Math.Abs(px - center) / (size * 0.5f);
				var ny = Math.Abs(py - center) / (size * 0.5f);
				var d = nx + ny;
				if (d > 1f)
				{
					image.SetPixel(px, py, Colors.Transparent);
					continue;
				}

				if (label == "hover_diamond_outline")
				{
					var edgeAlpha = Math.Clamp((d - 0.78f) / 0.22f, 0f, 1f);
					var innerFade = 1f - Math.Clamp((d - 0.15f) / 0.45f, 0f, 1f);
					var alpha = Math.Max(edgeAlpha, innerFade * 0.16f);
					image.SetPixel(px, py, new Color(color.R, color.G, color.B, alpha));
				}
				else
				{
					var edgeSoft = 1f - Math.Clamp((d - 0.80f) / 0.20f, 0f, 1f);
					var centerGlow = 1f - Math.Clamp(d / 0.72f, 0f, 1f);
					var alpha = Math.Clamp(0.22f + centerGlow * 0.62f + edgeSoft * 0.22f, 0f, 1f);
					image.SetPixel(px, py, new Color(color.R, color.G, color.B, alpha));
				}
				continue;
			}

			var dx = px - center;
			var dy = py - center;
			image.SetPixel(px, py, dx * dx + dy * dy <= radius * radius ? color : Colors.Transparent);
		}
		var tex = ImageTexture.CreateFromImage(image);
		_entityMarkerCache[label] = tex;
		return tex;
	}

	// ── Sprite Pool ──

	private void BeginFrame()
	{
		_spriteCount = 0;
		_faceBatchCanvas?.SetCommands(Array.Empty<FaceSpriteCommand>());
	}

	private void EndFrame()
	{
		for (var i = _spriteCount; i < _spritePool.Count; i++)
			_spritePool[i].Visible = false;
	}

	private Sprite2D AcquireSprite()
	{
		var idx = _spriteCount++;
		if (idx < _spritePool.Count) return _spritePool[idx];
		var sprite = new Sprite2D
		{
			Name = "VoxelSprite" + _spritePool.Count.ToString(),
			Centered = true,
			TextureFilter = CanvasItem.TextureFilterEnum.Nearest,
		};
		_root!.AddChild(sprite);
		_spritePool.Add(sprite);
		return sprite;
	}

	private void UpdateCamera(int cx, int cy, int cz)
	{
		if (_camera != null)
			_camera.Position = IsoCoordUtil.WorldToScreen(cx, cy, cz);
	}

	// ── Types ──

	private enum VoxelFace
	{
		Top,
		Left,
		Right,
	}

	public readonly record struct IsometricLightingSettings(
		float Ambient,
		float TopLight,
		float LeftLight,
		float RightLight,
		float DepthFalloff,
		float Contrast,
		float ShadowStrength,
		float OcclusionStep)
	{
		public IsometricLightingSettings Clamp(float minLight, float maxLight)
		{
			return new IsometricLightingSettings(
				Math.Clamp(Ambient, minLight, maxLight),
				Math.Clamp(TopLight, minLight, maxLight),
				Math.Clamp(LeftLight, minLight, maxLight),
				Math.Clamp(RightLight, minLight, maxLight),
				Math.Clamp(DepthFalloff, 0f, 0.35f),
				Math.Clamp(Contrast, 0.65f, 1.8f),
				Math.Clamp(ShadowStrength, 0f, 1.2f),
				Math.Clamp(OcclusionStep, 0f, 0.35f));
		}
	}

	private readonly record struct FaceSpriteCommand(
		Texture2D Texture,
		Vector2 Position,
		Color Tint,
		long SortKey);

	private sealed partial class VoxelFaceBatchCanvas : Node2D
	{
		private FaceSpriteCommand[] _commands = Array.Empty<FaceSpriteCommand>();

		public void SetCommands(IReadOnlyList<FaceSpriteCommand> commands)
		{
			if (commands.Count == 0)
			{
				_commands = Array.Empty<FaceSpriteCommand>();
				QueueRedraw();
				return;
			}

			if (_commands.Length != commands.Count)
				_commands = new FaceSpriteCommand[commands.Count];

			for (var i = 0; i < commands.Count; i++)
				_commands[i] = commands[i];

			QueueRedraw();
		}

		public override void _Draw()
		{
			for (var i = 0; i < _commands.Length; i++)
			{
				var cmd = _commands[i];
				if (cmd.Texture == null)
					continue;

				var size = cmd.Texture.GetSize();
				var rect = new Rect2(
					cmd.Position - size / 2f,
					size);
				DrawTextureRect(cmd.Texture, rect, false, cmd.Tint);
			}
		}
	}

